// Repassa pro painel toda mensagem de conversa individual (grupo, status e canal ficam de fora).
// Quem decide quem pode dar ordens é o painel (Configurações › WhatsApp), então trocar número não mexe aqui.
// Respostas do cérebro no chat "Você" começam com um caractere invisível (⁣) e são ignoradas (sem loop).
const saida = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const d = b.data || {};
  const chave = d.key || {};
  const remoto = String(chave.remoteJid || '');
  if (!remoto || remoto.endsWith('@g.us') || remoto.endsWith('@broadcast') || remoto.endsWith('@newsletter')) continue;
  const chat = [chave.remoteJidAlt, chave.senderPn, remoto].find((j) => String(j || '').endsWith('@s.whatsapp.net')) || '';
  if (!chat) continue;
  const m = d.message || {};
  const texto = m.conversation || m.extendedTextMessage?.text || '';
  if (texto.startsWith('⁣')) continue;
  const tipo = texto ? 'texto' : (d.messageType === 'audioMessage' ? 'audio' : 'outro');
  if (tipo === 'outro' && /reaction|protocol|senderKey|edited|poll|sticker/i.test(String(d.messageType))) continue;
  saida.push({ json: { texto, tipo, deMim: Boolean(chave.fromMe), chat, eu: String(b.sender || '') } });
}
return saida;
